  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Ef fi cacy and safety of tocilizumab in COVID-19 patients: a living systematic review and meta-analysis, fi rst update",
      "reason": "The title explicitly identifies the report as a systematic review ('a living systematic review and meta-analysis')."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Ef fi cacy and safety of tocilizumab in COVID-19 patients: a living systematic review and meta-analysis, fi rst update",
      "reason": "The title names the population (COVID-19 patients) and the intervention (tocilizumab) and the outcomes assessed (efficacy and safety)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "a living systematic review and meta-analysis, fi rst update",
      "reason": "The title includes supplementary information: analysis method (meta-analysis) and living-review/update status ('living', 'first update')."
    }
  ],
  "confidence": 97
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Cytokine release syndrome with elevated levels of interleukin-6 (IL-6) is associated with multiorgan damage and death in severe coronavirus disease 2019 (COVID-19). As of October 2020, cumulative moderate-certainty evidence from randomized controlled trials (RCTs) showed that the IL-6 receptor antagonist tocilizumab reduces the risk of mechanical ventilation in hospitalized COVID-19 patients, without affecting short-term mortality [1].",
      "reason": "The Introduction describes current knowledge on IL-6, tocilizumab, and remaining uncertainty about mortality effects."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "As several RCTs have been published since our initial review, and as per peer reviewers' and editor's recommendations, this update includes observational studies up to January 2021, and future updates will include only data from RCTs.",
      "reason": "The need for the updated review is explained by newly published RCTs and the living review design."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "This report is the fi rst update of our living systematic review assessing the ef fi - cacy and safety of tocilizumab in COVID-19 patients [1].",
      "reason": "This is an update and it explicitly identifies and cites the previous living systematic review (reference [1])."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Cytokine release syndrome with elevated levels of interleukin-6 (IL-6) is associated with multiorgan damage and death in severe coronavirus disease 2019 (COVID-19).",
      "reason": "The proposed mechanism (IL-6-driven cytokine release syndrome targeted by an IL-6 receptor antagonist) is briefly described."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "Tocilizumab is a single-drug intervention, not a complex intervention with multiple components; no logic model requirement applies."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Objectives: Cytokine release syndrome with elevated interleukin-6 (IL-6) levels is associated with multiorgan damage and death in severe coronavirus disease 2019 (COVID-19). Our objective was to update the data in a living systematic review of the literature concerning the efficacy and toxicity of the IL-6 receptor antagonist tocilizumab in COVID-19 patients.",
      "reason": "The abstract explicitly states the review objective: to update a living systematic review on the efficacy and toxicity of tocilizumab in COVID-19 patients."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "The participants were hospitalized COVID-19 patients, and intervention was tocilizumab versus placebo or standard of care.",
      "reason": "P, I, and C are clearly stated in the abstract methods (hospitalized COVID-19 patients; tocilizumab vs placebo/standard of care), and outcomes are implied by 'efficacy and toxicity' and the results reported (mortality, mechanical ventilation, composite poor outcome), but the planned outcomes are not fully enumerated within the objective statement itself."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Eligible studies were randomized controlled trials (RCTs) and observational studies at low or moderate risk of bias. The participants were hospitalized COVID-19 patients, and intervention was tocilizumab versus placebo or standard of care.",
      "reason": "The abstract states eligible designs (RCTs; observational studies at low/moderate risk of bias), population (hospitalized COVID-19 patients), intervention and comparator, but a full eligibility criteria section (e.g., settings, follow-up requirements) is not provided in the retrieved Methods text; the paper refers to prior review methodology."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of eligibility criteria regarding dissemination year, language, or publication status (e.g., preprints were searched but no explicit inclusion/exclusion rules for publication type, language, or date are reported)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not distinguish exclusion of studies because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Using available data from five studies [2,3,5 e 7], we assessed the effect of steroids on the composite of mortality or mechanical ventilation in patients taking tocilizumab versus controls. The risk ratios for patients receiving steroids and those not receiving steroids were 0.87 (95%CI 0.68 e 1.12) and 0.99 (95% 0.85 e 1.16) respectively.",
      "reason": "Synthesis groups (RCTs vs cohort studies; subgroup analyses by steroid use and mechanical ventilation status) and comparisons (tocilizumab vs control) are evident, but a Methods section explicitly specifying and linking groups for each synthesis to the review objectives is not fully described."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "As several RCTs have been published since our initial review, and as per peer reviewers' and editor's recommendations, this update includes observational studies up to January 2021, and future updates will include only data from RCTs.",
      "reason": "A rationale is given for including observational studies in this update and restricting future updates to RCTs, but no rationale is provided for other restrictions such as limiting observational studies to low or moderate risk of bias."
    }
  ],
  "confidence": 82
}

