      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to outcome-domain inclusion, definitions, or importance are reported with rationale; the only noted change concerns study design eligibility (inclusion of observational studies up to January 2021, future RCT-only updates)."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to processes for selecting results within outcome domains are reported."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit report of which outcomes were prioritized for interpreting conclusions with a rationale; the conclusion highlights certainty levels but does not describe prioritization methods."
